72	 */
73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
81	     * carrying the new owner's id, member id and registration date.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Dedicated notification logger. A single line is emitted here on each successful owner create,
87	     * enqueuing the new owner's welcome notification. The line carries the owner's id and its unified
88	     * {@code memberId}.
89	     */
90	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
91	
92	    /**
93	     * Source of the {@code seq} carried by each {@link OwnerCreatedEvent}: a monotonically increasing
94	     * counter bumped once per successful create, so every emitted event carries a strictly larger
95	     * sequence number than the create before it.
96	     */
97	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
98	
99	    /**
100	     * Maximum number of owners a single city may hold. A create whose city already contains this many
101	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
102	     */
103	    private static final int MAX_OWNERS_PER_CITY = 50;
104	
105	    /**
106	     * The number of owners a city must already hold before a create made for that city is flagged with
107	     * {@code capacityWarning}. Once the city holds at least this many owners (but still fewer than
108	     * {@link #MAX_OWNERS_PER_CITY}, so the create is not rejected), the new owner's {@code
109	     * capacityWarning} is {@code true}, signalling the city is approaching its capacity limit.
110	     */
111	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
112	
113	    /**
114	     * Maximum number of owners that may be registered in a single day. A create made once this many
115	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
116	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
117	     */
118	    private static final int MAX_OWNERS_PER_DAY = 100;
119	
120	    /**
121	     * The number of owners that must already carry a given day's {@code registrationDate} before a
122	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
123	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
124	     */
125	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
126	
127	    /**
128	     * Request header carrying the client-supplied idempotency key for a create. When a create repeats
129	     * with a key already seen, the originally created owner is returned with {@code 200 OK} instead of
130	     * creating a duplicate (see {@link #addOwner}).
131	     */
132	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
133	
134	    /**
135	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that create originally produced,
136	     * so a repeated create carrying the same key replays that owner rather than creating a duplicate.
137	     */
138	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
139	
140	    private final ClinicService clinicService;
141	
142	    private final OwnerMapper ownerMapper;
143	
144	    private final PetMapper petMapper;
145	
146	    private final VisitMapper visitMapper;
147	
148	    public OwnerRestControllerV1(ClinicService clinicService,
149	                                 OwnerMapper ownerMapper,
150	                                 PetMapper petMapper,
151	                                 VisitMapper visitMapper) {
152	        this.clinicService = clinicService;
153	        this.ownerMapper = ownerMapper;
154	        this.petMapper = petMapper;
155	        this.visitMapper = visitMapper;
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
161	        Collection<Owner> owners;
162	        if (lastName != null) {
163	            owners = this.clinicService.findOwnerByLastName(lastName);
164	        } else {
165	            owners = this.clinicService.findAllOwners();
166	        }
167	        if (owners.isEmpty()) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
186	        String idempotencyKey = idempotencyKey();
187	        if (idempotencyKey != null) {
188	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
189	            if (existingId != null) {
190	                Owner existing = this.clinicService.findOwnerById(existingId);
191	                if (existing != null) {
192	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
193	                }
194	            }
195	        }
196	        normalizeAddress(ownerFieldsDto);
197	        rejectBlankOwnerFields(ownerFieldsDto);
198	        rejectInvalidPostcode(ownerFieldsDto);
199	        normalizeTelephone(ownerFieldsDto);
200	        normalizeEmail(ownerFieldsDto);
201	        String householdId = householdIdFor(ownerFieldsDto);
202	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
203	        rejectDuplicateIdentity(ownerFieldsDto);
204	        long ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
205	        rejectCityAtCapacity(ownerFieldsDto.getCity(), ownersInCity);
206	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
207	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
208	        long registeredThatDay = countRegisteredOn(registrationDate);
209	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
210	        HttpHeaders headers = new HttpHeaders();
211	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
212	        owner.setRegistrationDate(registrationDate);
213	        owner.setHouseholdId(householdId);
214	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
215	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
216	        owner.setCapacityWarning(ownersInCity >= CAPACITY_WARNING_THRESHOLD);
217	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
218	        owner.setMembershipLevel(cappedMembershipLevel(owner));
219	        markPossibleDuplicate(owner, sharesHousehold);
220	        this.clinicService.saveOwner(owner);
221	        if (idempotencyKey != null) {
222	            this.idempotentCreates.put(idempotencyKey, owner.getId());
223	        }
224	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
225	        emitOwnerCreatedAudit(owner, ownerDto);
226	        enqueueWelcomeNotification(owner);
227	        headers.setLocation(UriComponentsBuilder.newInstance()
228	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
