491	    /**
492	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
493	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
494	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
495	     * {@code 400 Bad Request}.
496	     *
497	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
498	     *                       {@link #rejectBlankOwnerFields} having already run)
499	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
500	     */
501	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
502	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
503	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
504	        ownerFieldsDto.setTelephone(normalized);
505	    }
