530	    /**
531	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
532	     * duplicate detection is now expressed through the single derived {@code identityKey}
533	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
534	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
535	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
536	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
537	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
538	     * carry different telephones have different keys and are both allowed (they are instead recorded as
539	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
540	     * longer makes a duplicate.
541	     *
542	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
543	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
544	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
545	     */
546	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
547	        String identityKey = OwnerIdentity.identityKey(
548	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
549	        boolean inUse = activeOwners().stream()
550	            .map(OwnerIdentity::identityKey)
551	            .anyMatch(identityKey::equals);
552	        if (inUse) {
553	            throw new DuplicateOwnerIdentityException(identityKey);
554	        }
555	    }
