572	    /**
573	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
574	     * both match the submitted values, compared case-insensitively. The count reflects only owners
575	     * already persisted at the time of the create, so the owner being created is never included.
576	     *
577	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
578	     *                  having already run)
579	     * @param lastName  the submitted last name (non-blank here)
580	     * @return the number of existing owners sharing the same first and last name
581	     */
582	    private int countNamesakes(String firstName, String lastName) {
583	        return (int) this.clinicService.findAllOwners().stream()
584	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
585	                && lastName.equalsIgnoreCase(owner.getLastName()))
586	            .count();
