603	    /**
604	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
605	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
606	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
607	     * created is never among them.
608	     *
609	     * @param householdId the household identifier derived for the owner being created (see
610	     *                    {@link HouseholdNormalizer#toHouseholdId})
611	     * @return the existing owners already sharing that household (empty when {@code householdId} is
612	     *         {@code null})
613	     */
614	    private List<Owner> householdMembers(String householdId) {
615	        if (householdId == null) {
616	            return List.of();
617	        }
618	        return this.clinicService.findAllOwners().stream()
619	            .filter(member -> householdId.equals(member.getHouseholdId()))
620	            .toList();
621	    }
