623	    /**
624	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
625	     * {@code membershipLevel} among their existing household members. The owner's own level is the
626	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
627	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
628	     * owner's own level is returned unchanged.
629	     *
630	     * @param owner the owner being created, already stamped with its household id and size
631	     * @return the (possibly capped) membership level to stamp on the owner
632	     */
633	    private int cappedMembershipLevel(Owner owner) {
634	        int ownLevel = this.ownerMapper.membershipLevel(owner);
635	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
636	            .mapToInt(this.ownerMapper::membershipLevel)
637	            .max();
638	        return maxHouseholdLevel.isPresent()
639	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
640	            : ownLevel;
641	    }
