703	    /**
704	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
705	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
706	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
707	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
708	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
709	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
710	     * duplicate, so it is never flagged.
711	     *
712	     * @param owner           the owner being created, with telephone already normalized and
713	     *                        lastName/postcode set
714	     * @param sharesHousehold whether the request opted in to sharing a household
715	     */
716	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
717	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
718	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
719	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
720	    }
