1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
31	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
32	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * The owner's locality (region), the single value every region-derived field is built from: the
39	     * {@code locality} itself, the {@link #timezone timezone} and the {@link #ownerSegment
40	     * ownerSegment} area. It is the region component of the owner's {@code memberId} (see
41	     * {@link org.springframework.samples.petclinic.util.MemberId#region}). Routing all three readers
42	     * through this one accessor keeps them agreed on how an owner's region is obtained from its
43	     * identity.
44	     */
45	    default String locality(Owner owner) {
46	        return org.springframework.samples.petclinic.util.MemberId.region(owner.getMemberId());
47	    }
48	
49	    /**
50	     * The owner's {@code fiscalYear} label, {@code FY<YY>}, taken from the FY component of the owner's
51	     * {@code memberId} (see {@link org.springframework.samples.petclinic.util.MemberId#fiscalYearLabel}),
52	     * so the fiscal-year value references the unified member id.
53	     */
54	    default String fiscalYear(Owner owner) {
55	        return org.springframework.samples.petclinic.util.MemberId.fiscalYearLabel(owner.getMemberId());
56	    }
57	
58	    /**
59	     * Derives the owner's IANA {@code timezone} from its locality (region) via a fixed
60	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne}
61	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} for a region not in the table.
62	     */
63	    default String timezone(Owner owner) {
64	        String region = locality(owner);
65	        if (region == null) {
66	            return null;
67	        }
68	        return switch (region) {
69	            case "NSW" -> "Australia/Sydney";
70	            case "VIC" -> "Australia/Melbourne";
71	            case "QLD" -> "Australia/Brisbane";
72	            default -> null;
73	        };
74	    }
75	
76	    /**
77	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
78	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
79	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
80	     */
81	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
82	        java.time.LocalDate birthDate = owner.getBirthDate();
83	        java.time.LocalDate asOf = owner.getRegistrationDate();
84	        if (birthDate == null || asOf == null) {
85	            return null;
86	        }
87	        int years = java.time.Period.between(birthDate, asOf).getYears();
88	        if (years < 18) {
89	            return OwnerDto.AgeBandEnum.MINOR;
90	        }
91	        if (years < 65) {
92	            return OwnerDto.AgeBandEnum.ADULT;
93	        }
94	        return OwnerDto.AgeBandEnum.SENIOR;
95	    }
96	
97	    /**
98	     * Computes the owner's {@code membershipPoints}. Starts at 0; adds 2 when a non-blank email is
99	     * present; adds 1 when {@code namesakeCount} is 0; adds 2 for a household of 3 or more; adds 3
100	     * when at least one fiscal year has elapsed since {@code registrationDate} (measured from
101	     * {@code registrationDate} to today, counting 1-July boundaries crossed).
102	     */
103	    default int membershipPoints(Owner owner) {
104	        int points = 0;
105	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
106	            points += 2;
107	        }
108	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
109	            points += 1;
110	        }
111	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
112	            points += 2;
113	        }
114	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
115	        if (registrationDate != null
116	                && org.springframework.samples.petclinic.util.FiscalYear.elapsed(
117	                        registrationDate, java.time.LocalDate.now()) >= 1) {
118	            points += 3;
119	        }
120	        return points;
121	    }
122	
123	    /**
124	     * Reports the owner's {@code membershipLevel}. Uses the level stored on the owner when present
125	     * (as stamped on creation), otherwise falls back to the level {@linkplain #derivedMembershipLevel
126	     * derived} from its {@code membershipPoints}.
127	     */
128	    default int membershipLevel(Owner owner) {
129	        Integer stored = owner.getMembershipLevel();
130	        return stored != null ? stored : derivedMembershipLevel(owner);
131	    }
132	
133	    /**
134	     * Derives the owner's {@code membershipLevel} from {@code membershipPoints}: 1 for 0-1 points,
135	     * 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
136	     */
137	    default int derivedMembershipLevel(Owner owner) {
138	        int points = membershipPoints(owner);
139	        if (points <= 1) {
140	            return 1;
141	        }
142	        if (points <= 3) {
143	            return 2;
144	        }
145	        if (points <= 5) {
146	            return 3;
147	        }
148	        return 4;
149	    }
150	
151	    /**
152	     * Derives the owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
153	     * {@code PREMIUM} when {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise
154	     * {@code STANDARD}. AREA is {@code METRO} when the owner's locality is a known region
155	     * ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
156	     */
157	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
158	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
159	        String region = locality(owner);
160	        boolean metro = "NSW".equals(region) || "VIC".equals(region) || "QLD".equals(region);
161	        String area = metro ? "METRO" : "REGIONAL";
162	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
163	    }
164	
165	    /**
166	     * Composes the owner's {@code salutation} from its honorific {@code title} and {@code lastName}:
167	     * {@code title + ' ' + lastName} when a non-blank title is present, or just the {@code lastName}
168	     * when no title is given.
169	     */
170	    default String salutation(Owner owner) {
171	        String title = owner.getTitle();
172	        if (title == null || title.isBlank()) {
173	            return owner.getLastName();
174	        }
175	        return title + " " + owner.getLastName();
176	    }
177	
178	    Owner toOwner(OwnerDto ownerDto);
179	
180	    @Mapping(target = "id", ignore = true)
181	    @Mapping(target = "pets", ignore = true)
182	    Owner toOwner(OwnerFieldsDto ownerDto);
183	
184	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
185	
186	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
187	
188	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
189	        OwnerPageDto ownerPageDto = new OwnerPageDto();
190	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
191	        ownerPageDto.setPage(ownerPage.getNumber());
192	        ownerPageDto.setSize(ownerPage.getSize());
193	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
194	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
195	        return ownerPageDto;
196	    }
197	}
